{
    "level": "A2–B1",
    "intro": "У цій темі ти навчишся <strong>розрізняти прикметники та прислівники<\/strong>, правильно їх утворювати та використовувати в реченнях.",
    "rules": [
        {
            "label": "Adjectives",
            "color": "emerald",
            "text": "<strong>Прикметники<\/strong> описують іменники:",
            "example": "a quick answer, She is happy."
        },
        {
            "label": "Adverbs",
            "color": "blue",
            "text": "<strong>Прислівники<\/strong> описують дієслова:",
            "example": "He answered quickly. She smiled happily."
        },
        {
            "label": "Formation",
            "color": "amber",
            "text": "Більшість прислівників = <em>прикметник + -ly<\/em>:",
            "example": "slow → slowly, careful → carefully"
        }
    ]
}

{
    "title": "1. Основна різниця",
    "intro": "Прикметники та прислівники відповідають на різні питання та описують різні частини мови:",
    "rows": [
        {
            "en": "Adjectives",
            "ua": "Прикметники",
            "note": "Описують іменники (який? яка? яке?)"
        },
        {
            "en": "Adverbs",
            "ua": "Прислівники",
            "note": "Описують дієслова (як? коли? де?)"
        },
        {
            "en": "a beautiful dress",
            "ua": "гарна сукня",
            "note": "прикметник → описує dress"
        },
        {
            "en": "She dances beautifully.",
            "ua": "Вона танцює гарно.",
            "note": "прислівник → описує dances"
        }
    ],
    "warning": "💡 Запитай себе: що описується? Якщо іменник — використовуй прикметник, якщо дієслово — прислівник."
}

{
    "title": "2. Утворення прислівників",
    "sections": [
        {
            "label": "Загальне правило: + -ly",
            "color": "emerald",
            "description": "Більшість прислівників утворюються додаванням <strong>-ly<\/strong> до прикметника:",
            "examples": [
                {
                    "en": "quick → quickly",
                    "ua": "швидкий → швидко"
                },
                {
                    "en": "careful → carefully",
                    "ua": "обережний → обережно"
                },
                {
                    "en": "slow → slowly",
                    "ua": "повільний → повільно"
                }
            ]
        },
        {
            "label": "Закінчення на -y → -ily",
            "color": "blue",
            "description": "Якщо прикметник закінчується на <strong>-y<\/strong>, змінюємо на <strong>-ily<\/strong>:",
            "examples": [
                {
                    "en": "happy → happily",
                    "ua": "щасливий → щасливо"
                },
                {
                    "en": "easy → easily",
                    "ua": "легкий → легко"
                },
                {
                    "en": "angry → angrily",
                    "ua": "сердитий → сердито"
                }
            ]
        },
        {
            "label": "Закінчення на -le → -ly",
            "color": "sky",
            "description": "Якщо прикметник закінчується на <strong>-le<\/strong>, просто міняємо <strong>-e<\/strong> на <strong>-y<\/strong>:",
            "examples": [
                {
                    "en": "simple → simply",
                    "ua": "простий → просто"
                },
                {
                    "en": "gentle → gently",
                    "ua": "ніжний → ніжно"
                },
                {
                    "en": "terrible → terribly",
                    "ua": "жахливий → жахливо"
                }
            ]
        }
    ]
}

{
    "title": "3. Слова з однаковою формою",
    "sections": [
        {
            "label": "Fast, hard, late, early",
            "color": "emerald",
            "description": "Деякі слова мають <strong>однакову форму<\/strong> для прикметника та прислівника:",
            "examples": [
                {
                    "en": "a fast car \/ He drives fast.",
                    "ua": "швидка машина \/ Він їздить швидко."
                },
                {
                    "en": "hard work \/ She works hard.",
                    "ua": "важка робота \/ Вона працює важко."
                },
                {
                    "en": "an early morning \/ I woke up early.",
                    "ua": "ранній ранок \/ Я прокинувся рано."
                }
            ]
        },
        {
            "label": "Увага: hardly ≠ hard!",
            "color": "rose",
            "description": "<strong>Hardly<\/strong> означає «ледве, майже ні», а не «важко»:",
            "examples": [
                {
                    "en": "I can hardly see anything.",
                    "ua": "Я ледве щось бачу."
                },
                {
                    "en": "She hardly ever calls me.",
                    "ua": "Вона майже ніколи мені не телефонує."
                }
            ]
        },
        {
            "label": "Увага: lately ≠ late!",
            "color": "amber",
            "description": "<strong>Lately<\/strong> означає «останнім часом», а не «пізно»:",
            "examples": [
                {
                    "en": "I arrived late. (пізно)",
                    "ua": "Я прибув пізно."
                },
                {
                    "en": "Lately, I have been busy. (останнім часом)",
                    "ua": "Останнім часом я був зайнятий."
                }
            ]
        }
    ]
}

{
    "title": "4. Good vs Well",
    "intro": "Одна з найпоширеніших помилок — плутати <strong>good<\/strong> (прикметник) з <strong>well<\/strong> (прислівник):",
    "rows": [
        {
            "en": "She is a good singer.",
            "ua": "Вона гарна співачка.",
            "note": "✓ прикметник good описує singer"
        },
        {
            "en": "She sings well.",
            "ua": "Вона гарно співає.",
            "note": "✓ прислівник well описує sings"
        },
        {
            "en": "❌ She sings good.",
            "ua": "ПОМИЛКА!",
            "note": "Потрібно: She sings well."
        },
        {
            "en": "❌ She is a well singer.",
            "ua": "ПОМИЛКА!",
            "note": "Потрібно: She is a good singer."
        }
    ],
    "warning": "💡 <strong>Well<\/strong> як прикметник означає «здоровий»: I feel well today (Я почуваюся добре сьогодні)."
}

{
    "title": "5. Позиція в реченні",
    "sections": [
        {
            "label": "Прикметники",
            "color": "emerald",
            "description": "Прикметники стоять <strong>перед іменником<\/strong> або <strong>після to be \/ linking verbs<\/strong>:",
            "examples": [
                {
                    "en": "an expensive car (перед іменником)",
                    "ua": "дорога машина"
                },
                {
                    "en": "The car is expensive. (після to be)",
                    "ua": "Машина дорога."
                },
                {
                    "en": "The soup smells delicious. (після linking verb)",
                    "ua": "Суп пахне смачно."
                }
            ]
        },
        {
            "label": "Прислівники",
            "color": "blue",
            "description": "Прислівники зазвичай стоять <strong>після дієслова<\/strong> або <strong>в кінці речення<\/strong>:",
            "examples": [
                {
                    "en": "He speaks clearly.",
                    "ua": "Він говорить чітко."
                },
                {
                    "en": "She answered the question correctly.",
                    "ua": "Вона відповіла на питання правильно."
                },
                {
                    "en": "They drive carefully.",
                    "ua": "Вони їздять обережно."
                }
            ]
        },
        {
            "label": "Прислівники частотності",
            "color": "sky",
            "description": "Прислівники частотності (always, usually, often) стоять <strong>перед основним дієсловом<\/strong>:",
            "examples": [
                {
                    "en": "I always wake up early.",
                    "ua": "Я завжди прокидаюся рано."
                },
                {
                    "en": "She never drinks coffee.",
                    "ua": "Вона ніколи не п'є каву."
                }
            ]
        }
    ]
}

{
    "title": "6. Типові помилки",
    "sections": [
        {
            "label": "Помилка 1: Real \/ Really",
            "color": "rose",
            "description": "<strong>Real<\/strong> — прикметник (справжній), <strong>really<\/strong> — прислівник (дійсно, дуже):",
            "examples": [
                {
                    "en": "✓ This is a real diamond. (справжній діамант)",
                    "ua": "Це справжній діамант."
                },
                {
                    "en": "✓ I really like this song. (дійсно подобається)",
                    "ua": "Мені дуже подобається ця пісня."
                },
                {
                    "en": "❌ I real like this. → ✓ I really like this.",
                    "ua": "ПОМИЛКА"
                }
            ]
        },
        {
            "label": "Помилка 2: Bad \/ Badly",
            "color": "rose",
            "description": "<strong>Bad<\/strong> — прикметник (поганий), <strong>badly<\/strong> — прислівник (погано):",
            "examples": [
                {
                    "en": "✓ I feel bad. (почуваюся погано)",
                    "ua": "Я почуваюся погано."
                },
                {
                    "en": "✓ He played badly. (грав погано)",
                    "ua": "Він грав погано."
                },
                {
                    "en": "❌ He played bad. → ✓ He played badly.",
                    "ua": "ПОМИЛКА"
                }
            ]
        },
        {
            "label": "Помилка 3: Після linking verbs",
            "color": "amber",
            "description": "Після <strong>linking verbs<\/strong> (feel, look, smell, taste, sound) використовуємо <strong>прикметник<\/strong>:",
            "examples": [
                {
                    "en": "✓ The food tastes good. (не goodly)",
                    "ua": "Їжа смакує добре."
                },
                {
                    "en": "✓ You look tired. (не tiredly)",
                    "ua": "Ти виглядаєш втомленим."
                },
                {
                    "en": "✓ This sounds interesting. (не interestingly)",
                    "ua": "Це звучить цікаво."
                }
            ]
        }
    ]
}

{
    "title": "7. Зміна значення з -ly",
    "intro": "Деякі слова мають різне значення як прикметник і як прислівник з -ly:",
    "rows": [
        {
            "en": "hard \/ hardly",
            "ua": "важко \/ ледве",
            "note": "He works hard. \/ He hardly works."
        },
        {
            "en": "late \/ lately",
            "ua": "пізно \/ останнім часом",
            "note": "I arrived late. \/ Lately, I am busy."
        },
        {
            "en": "near \/ nearly",
            "ua": "близько \/ майже",
            "note": "Come near. \/ I nearly forgot."
        },
        {
            "en": "high \/ highly",
            "ua": "високо \/ дуже (високо оцінюється)",
            "note": "Fly high. \/ Highly recommended."
        },
        {
            "en": "short \/ shortly",
            "ua": "коротко \/ незабаром",
            "note": "Cut it short. \/ I will call shortly."
        }
    ],
    "warning": "💡 Завжди перевіряй значення слова з -ly у словнику — воно може відрізнятися від базового прикметника!"
}

{
    "title": "8. Практичні поради",
    "intro": "Як визначити, що використовувати — прикметник чи прислівник:",
    "items": [
        {
            "label": "Крок 1",
            "title": "Визнач, що описується",
            "subtitle": "Іменник → прикметник. Дієслово → прислівник."
        },
        {
            "label": "Крок 2",
            "title": "Постав питання",
            "subtitle": "Який? Яка? → прикметник. Як? → прислівник."
        },
        {
            "label": "Крок 3",
            "title": "Перевір форму",
            "subtitle": "Більшість прислівників мають закінчення -ly."
        },
        {
            "label": "Крок 4",
            "title": "Пам'ятай винятки",
            "subtitle": "fast, hard, early, late — однакові форми!"
        }
    ]
}

{
    "title": "9. Додаткові випадки",
    "sections": [
        {
            "label": "Прислівники, що описують прикметники",
            "color": "emerald",
            "description": "Прислівники можуть описувати <strong>прикметники<\/strong> для підсилення або послаблення:",
            "examples": [
                {
                    "en": "It is extremely hot today.",
                    "ua": "Сьогодні надзвичайно спекотно."
                },
                {
                    "en": "She is very beautiful.",
                    "ua": "Вона дуже гарна."
                },
                {
                    "en": "This is quite interesting.",
                    "ua": "Це досить цікаво."
                }
            ]
        },
        {
            "label": "Прислівники, що описують прислівники",
            "color": "blue",
            "description": "Прислівники можуть описувати інші <strong>прислівники<\/strong>:",
            "examples": [
                {
                    "en": "He drives very carefully.",
                    "ua": "Він їздить дуже обережно."
                },
                {
                    "en": "She speaks extremely quickly.",
                    "ua": "Вона говорить надзвичайно швидко."
                },
                {
                    "en": "They work surprisingly well together.",
                    "ua": "Вони напрочуд добре працюють разом."
                }
            ]
        }
    ]
}

{
    "title": "Продовжуй навчання",
    "items": [
        {
            "label": "Degrees of Comparison — Ступені порівняння",
            "current": false
        },
        {
            "label": "Comparative vs Superlative — Вибір форми",
            "current": false
        },
        {
            "label": "Equality Comparison — as ... as / not as ... as",
            "current": false
        },
        {
            "label": "Adjectives vs Adverbs — Прикметники й прислівники",
            "current": true
        }
    ]
}

{
    "level": "B1",
    "intro": "У цій темі ти навчишся вибудовувати прикметники за типовою англійською схемою: <strong>opinion, size, age, shape, color, origin, material, purpose</strong>.",
    "rules": [
        {
            "label": "TYPICAL ORDER",
            "color": "emerald",
            "text": "Найуживаніша схема: <strong>opinion → size → age → shape → color → origin → material → purpose</strong>.",
            "example": "a lovely small old round brown Italian wooden table"
        },
        {
            "label": "NOT ALL SLOTS",
            "color": "blue",
            "text": "Не треба заповнювати всі позиції. Більшість речень мають лише 1–3 прикметники.",
            "example": "a nice blue shirt"
        },
        {
            "label": "CLOSE TO NOUN",
            "color": "amber",
            "text": "Найближче до іменника часто стоять <strong>material</strong> і <strong>purpose</strong>.",
            "example": "a black leather jacket / a sleeping bag"
        }
    ]
}

{
    "title": "1. Типовий порядок",
    "intro": "Запам’ятай найпоширенішу послідовність.",
    "items": [
        {
            "label": "1",
            "title": "opinion",
            "subtitle": "nice, ugly, beautiful"
        },
        {
            "label": "2",
            "title": "size",
            "subtitle": "big, small, tall"
        },
        {
            "label": "3",
            "title": "age / shape",
            "subtitle": "old, young, round, square"
        },
        {
            "label": "4",
            "title": "color / origin",
            "subtitle": "red, blue, Italian, Ukrainian"
        },
        {
            "label": "5",
            "title": "material / purpose",
            "subtitle": "wooden, metal, sleeping, racing"
        },
        {
            "label": "6",
            "title": "noun",
            "subtitle": "bag, table, shoes, car"
        }
    ]
}

{
    "title": "2. Як це звучить природно",
    "sections": [
        {
            "label": "Короткі природні фрази",
            "color": "emerald",
            "description": "У реальному мовленні часто достатньо двох або трьох прикметників.",
            "examples": [
                {
                    "en": "a beautiful old house",
                    "ua": "гарний старий будинок"
                },
                {
                    "en": "a small black dog",
                    "ua": "маленький чорний пес"
                },
                {
                    "en": "an expensive Italian car",
                    "ua": "дорога італійська машина"
                }
            ]
        },
        {
            "label": "Довші ланцюжки",
            "color": "blue",
            "description": "Якщо прикметників більше, порядок стає важливішим.",
            "examples": [
                {
                    "en": "a lovely small old round table",
                    "ua": "милий маленький старий круглий стіл"
                },
                {
                    "en": "a big modern glass office building",
                    "ua": "велика сучасна скляна офісна будівля"
                },
                {
                    "en": "a stylish long black wool coat",
                    "ua": "стильне довге чорне вовняне пальто"
                }
            ]
        },
        {
            "label": "Material і purpose біля іменника",
            "color": "amber",
            "description": "Слова на кшталт <strong>wooden, plastic, sleeping, racing</strong> зазвичай стоять близько до іменника.",
            "examples": [
                {
                    "en": "a large brown wooden box",
                    "ua": "велика коричнева дерев’яна коробка"
                },
                {
                    "en": "a light blue sleeping bag",
                    "ua": "світло-синій спальник"
                },
                {
                    "en": "a fast red racing bike",
                    "ua": "швидкий червоний гоночний велосипед"
                }
            ],
            "note": "Purpose adjectives часто поводяться майже як частина іменника."
        }
    ]
}

{
    "title": "3. Типові помилки",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Неприродний порядок.",
            "wrong": "a wooden old box",
            "right": "✅ <span class=\"font-mono\">an old wooden box</span>"
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Color перед size без причини.",
            "wrong": "a black small dog",
            "right": "✅ <span class=\"font-mono\">a small black dog</span>"
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Purpose занадто далеко від іменника.",
            "wrong": "a sleeping blue warm bag",
            "right": "✅ <span class=\"font-mono\">a warm blue sleeping bag</span>"
        }
    ]
}

{
    "title": "4. Короткий конспект",
    "items": [
        "Типова схема: <strong>opinion → size → age → shape → color → origin → material → purpose → noun</strong>.",
        "У реальному мовленні часто достатньо 1–3 прикметників.",
        "Color зазвичай іде після size / age / shape.",
        "Material і purpose часто стоять найближче до іменника.",
        "Якщо сумніваєшся, краще вжити менше прикметників, але в природному порядку."
    ]
}

